def seed_quests():
    """Insert default daily quests into the database."""
    # NOT: bu liste app/db_init.py'nin tohumladığı 8 quest_type ile eş tutulmalı
    # (drift → görev ekonomisi CLI'dan seed edilen ortamlarda eksik kalırdı).
    defaults = [
        {"title": "Günlük Giriş", "description": "Bugün uygulamaya giriş yap", "points_reward": 10, "quest_type": "login"},
        {"title": "Antrenman Kaydet", "description": "Bir antrenman planı oluştur veya kaydet", "points_reward": 50, "quest_type": "workout_logged"},
        {"title": "Bir Arkadaşına Yardım Et", "description": "Bir arkadaşına mesaj gönder", "points_reward": 30, "quest_type": "suggestion_sent"},
        {"title": "Dolabını Güncelle", "description": "Supplement dolabına yeni bir ürün ekle", "points_reward": 25, "quest_type": "supplement_added"},
        {"title": "Öğün Kaydet", "description": "Bugün bir öğün kaydet", "points_reward": 20, "quest_type": "meal_logged"},
        {"title": "Su Hedefi", "description": "Bugün su takibini güncelle", "points_reward": 10, "quest_type": "water_logged"},
        {"title": "Haftalık Check-in", "description": "Kilonu güncelle veya check-in yap", "points_reward": 20, "quest_type": "checkin_done"},
        {"title": "Bir Arkadaşını Davet Et", "description": "Davet bağlantını bir arkadaşınla paylaş", "points_reward": 40, "quest_type": "friend_invited"},
    ]
    for q in defaults:
        existing = DailyQuest.query.filter_by(quest_type=q["quest_type"]).first()
        if not existing:
            db.session.add(DailyQuest(**q))
    db.session.commit()
    click.echo("Default quests seeded successfully.")


def weekly_reset_cmd():
    """Snapshot the weekly board, award top-3 XP, reset weekly_xp. Idempotent.

    Hafta sınırı artık Istanbul'da hesaplanır (B1: weekly_xp Istanbul günlerinde
    birikir). EC2 host cron `59 23 * * 0` (Sunday 23:59 UTC = Pazartesi 02:59
    Istanbul) tamamlanmış haftadan hemen sonra çalışır; idempotent olduğu için
    (WeeklyResetLog) bu ~3 saatlik gecikme yalnızca bildirimi geciktirir, yanlış
    hafta işlemez. Sınıra tam hizalamak istenirse cron'u `59 20 * * 0` (Sunday
    20:59 UTC = Pazar 23:59 Istanbul) yapın.
        flask --app starter weekly-reset
    """
    click.echo(run_weekly_rollover())
    # I5: haftalık bakım penceresinde 30+ gün dokunulmamış Cognito oturum
    # satırlarını da süpür (refresh penceresi dolmuştur, yenilenemezler).
    #
    # M1: süpürme ARTIK yalnızca bu cron'a BAĞLI DEĞİL. app/hooks.py, rollover ile
    # aynı Redis NX-kilit desenini kullanarak günde bir kez uygulama içinden de
    # süpürür — çünkü bu komutun varsaydığı host cron'u repo'da hiçbir yerde
    # kurulmuyordu (bir host yeniden kurulumunda sessizce kaybolabilirdi ve
    # tablo sınırsız büyümeye devam ederdi). Burada kalması zararsız: idempotent.
    from flask import current_app
    from app.services import session_store
    removed = session_store.purge_expired()
    click.echo(f"cognito-sessions purged: {removed}")
    if current_app.config["MOBILE_AUTH_ENABLED"]:
        from app.services import mobile_auth
        mobile_removed = mobile_auth.purge_expired()
    else:
        mobile_removed = 0
    click.echo(f"mobile-auth-sessions purged: {mobile_removed}")



@click.argument("recipient")
def send_test_email_cmd(recipient):
    """E-posta altyapısını (Resend) uçtan uca doğrula — test e-postası gönder.

    Yalnızca geliştirme/doğrulama içindir (Email Sprint 1); iş mantığına
    dokunmaz. RESEND_API_KEY ayarlı değilse servis kapalıdır ve gönderim
    yapılmaz.

        flask --app starter send-test-email you@example.com
    """
    from app.services import email_service

    if not email_service.is_enabled():
        click.echo("E-posta servisi kapalı: RESEND_API_KEY ayarlı değil (.env).")
        return
    message_id = email_service.send_test_email(recipient)
    if message_id:
        click.echo(f"Test e-postası gönderildi: id={message_id} -> {recipient}")
    else:
        click.echo("Test e-postası GÖNDERİLEMEDİ — ayrıntı için loglara bakın.")


# Varsayılan "test/seed hesabı" kalıbı — sadece açıkça tohum/deneme gibi görünen
# kullanıcı adları. Gerçek kullanıcıları yanlışlıkla yakalamamak için dar tutuldu.
_DEFAULT_TEST_RE = re.compile(
    r"^(test|tester|testuser|seed|demo|dummy|sample|deneme|bulk|qa)\d*$", re.I)


# B4: user_id taşıyan HER model bu listede olmalı (test_cascade_delete
# introspeksiyonla doğrular) — SQLite'ta FK cascade'e güvenmeden açık silme.
# Sıra FK-güvenli: PumpCheckLike/Comment, PumpCheck'ten önce gelir.
def _user_child_models():
    from app.models import (
        Activity, CoachConversation, CognitoSession, CustomMeal, DailyActivity,
        FeedHide, FeedItem, FeedItemComment, FeedItemLike, FeedReport,
        MealLog, MobileAuthSession, Notification, NutritionPlan, PendingAction,
        PlanMutationRecord, TrainingPlanConfirmationProposal, PumpCheck,
        PumpCheckComment, PumpCheckComparison, PumpCheckComparisonRequest,
        PumpCheckLike, Supplement, TrainingPlan,
        UserBadge, UserChallengeProgress, UserQuestProgress, UserSession,
        UserWearableConnection, WaterLog,
        WearableActivityLog, WearableSleepLog, WearableWorkoutLog,
        WeeklyCheckIn, WeeklyLog, WeeklyWinner, WorkoutLog, WorkoutSession,
    )
    return (
        UserSession, CognitoSession, MobileAuthSession, WeeklyLog, WeeklyCheckIn, NutritionPlan,
        # PlanMutationRecord before TrainingPlan: the journal describes plan
        # history, so nothing should ever observe entries for a plan that is
        # already gone.
        PlanMutationRecord, TrainingPlanConfirmationProposal, TrainingPlan,
        MealLog, PendingAction, PumpCheckLike, PumpCheckComment,
        # Sprint 10 PR3: the request ledger points at the comparison, and the
        # comparison points at both source Pump Checks — so erasure runs
        # ledger, then comparison, then the sources below.
        PumpCheckComparisonRequest, PumpCheckComparison,
        PumpCheck, Activity, Supplement, UserQuestProgress, WeeklyWinner,
        WaterLog, WorkoutLog, WorkoutSession, DailyActivity, CustomMeal,
        CoachConversation,
        UserWearableConnection, WearableSleepLog, WearableActivityLog,
        WearableWorkoutLog, FeedItemLike, FeedItemComment, FeedItem,
        FeedHide, FeedReport, Notification,
        UserChallengeProgress, UserBadge,
    )


# Modül-yükünde app context/model importu gerekmeden test edilebilsin diye tembel.
class _LazyChildModels:
    def __iter__(self):
        return iter(_user_child_models())

    def __contains__(self, item):
        return item in _user_child_models()


_USER_CHILD_MODELS = _LazyChildModels()


def _purge_user(user):
    """Bir kullanıcıyı ve ona bağlı tüm satırları FK-güvenli sırada sil.

    FK'lerde artık ON DELETE CASCADE var (migration a1b2c3d4e5f6 + model ondelete),
    yani Postgres'te user silmek bağımlıları zaten süpürürdü. Yine de bağımlıları
    elle siliyoruz: SQLite (lokal/test) FK eylemlerini varsayılan olarak
    zorlamaz (PRAGMA foreign_keys kapalı), ve açık silme niyeti belirsizliğe yer
    bırakmaz. Bu kullanıcının davet ettiği kişilerin referred_by_id'si NULL'a
    çekilir (FK'de SET NULL olsa da burada da açıkça yapılır).
    """
    from app.models import (CoachConversation, CoachMessage, CustomMeal,
                            CustomMealItem, Friendship, Message, Notification,
                            PumpCheck, PumpCheckComment, PumpCheckLike, User)
    uid = user.id

    # Bildirimler iki yönden bağlı: kullanıcının ALDIKLARI (user_id — aşağıdaki
    # child-model döngüsü siler) VE tetiklediği (actor_id) — actor tarafı burada
    # açıkça süpürülür (SQLite FK cascade zorlamaz).
    Notification.query.filter(Notification.actor_id == uid).delete(
        synchronize_session=False)

    # CustomMealItem yalnızca custom_meal üzerinden user'a bağlı.
    meal_ids = [m.id for m in CustomMeal.query.filter_by(user_id=uid).all()]
    if meal_ids:
        CustomMealItem.query.filter(
            CustomMealItem.custom_meal_id.in_(meal_ids)
        ).delete(synchronize_session=False)

    # CoachMessage de yalnızca coach_conversation üzerinden user'a bağlı
    # (user_id taşımaz) — konuşmalar aşağıdaki döngüde silinmeden ÖNCE süpürülür.
    conv_ids = [c.id for c in CoachConversation.query.filter_by(user_id=uid).all()]
    if conv_ids:
        CoachMessage.query.filter(
            CoachMessage.conversation_id.in_(conv_ids)
        ).delete(synchronize_session=False)

    # Like/yorumlar iki yönden bağlı: kullanıcının kendi bıraktıkları (user_id)
    # VE başkalarının bu kullanıcının pump check'lerine bıraktıkları
    # (pump_check_id) — tek or-filtre ikisini de süpürür.
    pump_ids = [p.id for p in PumpCheck.query.filter_by(user_id=uid).all()]
    pump_child_filter = [PumpCheckLike.user_id == uid]
    comment_child_filter = [PumpCheckComment.user_id == uid]
    if pump_ids:
        pump_child_filter.append(PumpCheckLike.pump_check_id.in_(pump_ids))
        comment_child_filter.append(PumpCheckComment.pump_check_id.in_(pump_ids))
    PumpCheckLike.query.filter(db.or_(*pump_child_filter)).delete(
        synchronize_session=False)
    PumpCheckComment.query.filter(db.or_(*comment_child_filter)).delete(
        synchronize_session=False)

    # Feed V2 (Sprint 5 PR2): FeedItem like/yorumları iki yönden bağlı —
    # kullanıcının kendi bıraktıkları (user_id, döngü siler) VE başkalarının bu
    # kullanıcının feed item'larına bıraktıkları (feed_item_id). Ayrıca
    # başkalarının bu kullanıcının pump check'lerine yaptığı repost'lar (ref_id,
    # FK'siz) askıda kalmasın diye açıkça silinir — child-model döngüsünden ÖNCE.
    from app.models import FeedItem, FeedItemComment, FeedItemLike
    own_item_ids = [i for (i,) in db.session.query(FeedItem.id).filter(FeedItem.user_id == uid).all()]
    ref_item_ids = []
    if pump_ids:
        ref_item_ids = [i for (i,) in db.session.query(FeedItem.id).filter(
            FeedItem.ref_type == "pump_check", FeedItem.ref_id.in_(pump_ids)).all()]
    all_item_ids = set(own_item_ids) | set(ref_item_ids)
    fi_like_filter = [FeedItemLike.user_id == uid]
    fi_comment_filter = [FeedItemComment.user_id == uid]
    if all_item_ids:
        fi_like_filter.append(FeedItemLike.feed_item_id.in_(all_item_ids))
        fi_comment_filter.append(FeedItemComment.feed_item_id.in_(all_item_ids))
    FeedItemLike.query.filter(db.or_(*fi_like_filter)).delete(synchronize_session=False)
    FeedItemComment.query.filter(db.or_(*fi_comment_filter)).delete(synchronize_session=False)
    if ref_item_ids:
        FeedItem.query.filter(FeedItem.id.in_(ref_item_ids)).delete(synchronize_session=False)

    for Model in _USER_CHILD_MODELS:
        Model.query.filter_by(user_id=uid).delete(synchronize_session=False)

    Friendship.query.filter(
        db.or_(Friendship.sender_id == uid, Friendship.receiver_id == uid)
    ).delete(synchronize_session=False)
    Message.query.filter(
        db.or_(Message.sender_id == uid, Message.receiver_id == uid)
    ).delete(synchronize_session=False)

    User.query.filter_by(referred_by_id=uid).update(
        {"referred_by_id": None}, synchronize_session=False)

    db.session.delete(user)


@click.option("--username", default=None,
              help="Tek bir kullanıcı adını hedefle (tam, büyük/küçük harf duyarsız).")
@click.option("--pattern", default=None,
              help="Özel regex (verilmezse varsayılan test/seed kalıbı kullanılır).")
@click.option("--yes", is_flag=True, help="Onayla ve gerçekten sil (yoksa kuru çalışma).")
def cleanup_test_users(username, pattern, yes):
    """Sızıntı kalan test/seed hesaplarını (ör. 'test') sil.

    Varsayılan KURU ÇALIŞMA — sadece eşleşenleri listeler. Silmek için --yes ekleyin:

        flask --app starter cleanup-test-users                 # önizleme
        flask --app starter cleanup-test-users --yes           # sil
        flask --app starter cleanup-test-users --username test --yes
    """
    from app.models import User

    if username:
        users = User.query.filter(
            db.func.lower(User.username) == username.lower()).all()
    else:
        rx = re.compile(pattern, re.I) if pattern else _DEFAULT_TEST_RE
        users = [u for u in User.query.all() if rx.match(u.username or "")]

    if not users:
        click.echo("Eşleşen test kullanıcısı bulunamadı.")
        return

    click.echo(f"{len(users)} kullanıcı eşleşti:")
    for u in users:
        click.echo(f"  - id={u.id}  username={u.username!r}  email={u.email}  "
                   f"xp={u.rank_points or 0}")

    if not yes:
        click.echo("\nKURU ÇALIŞMA — hiçbir şey silinmedi. Silmek için --yes ekleyin.")
        return

    for u in users:
        _purge_user(u)
    db.session.commit()

    # Liderlik sorted set'lerinden de düşsünler.
    try:
        from app.services.gamification import lb_rebuild
        lb_rebuild()
    except Exception:
        pass

    click.echo(f"\n✓ {len(users)} kullanıcı ve ilişkili kayıtları silindi.")


def rq_failed_cmd():
    """WS8: ölü-mektup (dead-letter) kuyruğunu listele — retry'ı tükenmiş işler.

        flask --app starter rq-failed
    """
    from app.jobs import failed_jobs
    ids = failed_jobs()
    if not ids:
        click.echo("Başarısız iş yok (ya da rq/Redis yapılandırılmamış).")
        return
    click.echo(f"{len(ids)} başarısız iş:")
    for jid in ids:
        click.echo(f"  - {jid}")
    click.echo("\nYeniden kuyruğa almak için: flask --app starter rq-requeue <job_id>")


@click.argument("job_id")
def rq_requeue_cmd(job_id):
    """WS8: başarısız bir işi yeniden kuyruğa al.

        flask --app starter rq-requeue <job_id>
    """
    from app.jobs import requeue_failed
    if requeue_failed(job_id):
        click.echo(f"İş yeniden kuyruğa alındı: {job_id}")
    else:
        click.echo(f"Yeniden kuyruğa alınamadı: {job_id} (bulunamadı ya da rq/Redis yok).")


def register_cli(app):
    app.cli.command("seed-quests")(seed_quests)
    app.cli.command("weekly-reset")(weekly_reset_cmd)
    app.cli.command("cleanup-test-users")(cleanup_test_users)
    app.cli.command("send-test-email")(send_test_email_cmd)
    app.cli.command("rq-failed")(rq_failed_cmd)
    app.cli.command("rq-requeue")(rq_requeue_cmd)
